def parse_attendees(text: str) -> tuple[list[dict], list[str]]:
    attendees = []
    errors = []
    lines = text.splitlines()
    header = [h.strip().lower() for h in lines[0].split(",")]
    for lineno, line in enumerate(lines[1:], start=1):
        if not line.strip():
            continue
        values = [v.strip() for v in line.split(",")]
        row = dict(zip(header, values))
        email = row.get("email", "")
        if not email:
            errors.append(f"line {lineno}: missing email")
            continue
        attendees.append({
            "name": row.get("name", ""),
            "email": email.lower(),
            "ticket": row.get("ticket", "general"),
        })
    return attendees, errors
